import pytest
from datetime import UTC, datetime
from subject import extract_registry_update
from omnibase_infra.services.session_registry.enum_session_phase import EnumSessionPhase
from omnibase_infra.services.session_registry.enum_session_registry_status import EnumSessionRegistryStatus


@pytest.mark.unit
def test_extract_registry_update_valid_event():
    event = {
        "task_id": "task-123",
        "session_id": "session-456",
        "correlation_id": "corr-789",
        "event_type": "session.started",
        "emitted_at": "2023-10-01T12:00:00+00:00"
    }
    result = extract_registry_update(event)
    assert result is not None
    assert result.task_id == "task-123"
    assert result.status == EnumSessionRegistryStatus.ACTIVE
    assert result.current_phase == EnumSessionPhase.PLANNING
    assert result.session_ids == ["session-456"]
    assert result.correlation_ids == ["corr-789"]
    assert result.last_activity == datetime.fromisoformat("2023-10-01T12:00:00+00:00")
    assert result.files_touched == []


